const hash = (v:any) => crypto.createHash('sha256').update(JSON.stringify(canonical(v))).digest('hex')
const union = (boxes:any[]) => boxes.length ? {left:Math.min(...boxes.map(b=>b.left)),top:Math.min(...boxes.map(b=>b.top)),right:Math.max(...boxes.map(b=>b.right)),bottom:Math.max(...boxes.map(b=>b.bottom))} : null
const area = (b:any) => b ? Math.max(0,b.right-b.left)*Math.max(0,b.bottom-b.top) : 0
const itemBox = (i:any) => i.rot!==undefined && Math.abs(i.rot+90)<0.01 ? {left:i.x-i.h, right:i.x, top:i.y-i.w,bottom:i.y} : {left:i.x,right:i.x+i.w,top:i.y-i.h,bottom:i.y}
const blockRegions = new WeakMap<object,any>()
let page:any, current:any, pending:any
const tokenItems = new WeakMap<object,any[]>(), series = new WeakMap<object,any>()
const makeRegion = (items:any[]) => {const bbox=union(items.map(itemBox));return {bbox,degenerate:area(bbox)===0,item_indexes:[...new Set(items.map(i=>page.items.indexOf(i)))].sort((a:any,b:any)=>a-b)}}
;(globalThis as any).__census = {
  tokenItems,
  table(rows:any[],anchor:any) {pending={...makeRegion(rows.flatMap(r=>r.items)),title:anchor.titleText,row_count:rows.length}},
  list(result:any) {current.lists.push({...pending,index:current.lists.length,listKind:result.listKind,candidates:result.candidates.length,issue:result.issue??null})},
  block(block:any,alongKey:string) {const x=alongKey==='x'?block.xGrid.axes:block.yGrid.axes,y=alongKey==='y'?block.xGrid.axes:block.yGrid.axes;const bbox={left:Math.min(...x.map((a:any)=>a.positionPt)),right:Math.max(...x.map((a:any)=>a.positionPt)),top:Math.min(...y.map((a:any)=>a.positionPt)),bottom:Math.max(...y.map((a:any)=>a.positionPt))};blockRegions.set(block,{title:block.title??null,placements:block.placements.length,x_grid_along_key:alongKey,bbox,degenerate:area(bbox)===0})},
  series(candidate:any,chain:any[],labels:any[]) {series.set(candidate,{...makeRegion([...chain,...labels].flatMap(t=>tokenItems.get(t)!)),dimension_tokens:chain.map(t=>({text:t.text,x:t.x,y:t.y})),label_tokens:labels.map(t=>({text:t.text,x:t.x,y:t.y})),titleItems:[]})},
  title(candidate:any,title:any) {if(candidate)series.get(candidate).titleItems.push(...tokenItems.get(title)!)},
  resolved(candidates:any[]) {current.elevations=candidates.map((c,index)=>{const s=series.get(c),with_titles=makeRegion([...s.item_indexes.map((i:number)=>page.items[i]),...s.titleItems]);const {titleItems,...rest}=s;return {...rest,index,titles:c.titles,with_titles}})}
}
